/**
 * The interaction layer of the homepage scenes. The scenes are pictures of the
 * app that respond like it: the top bar tools open and close their dropdowns,
 * and every control with a `title` shows the app's tooltip. Nothing runs.
 */
import {
  createContext,
  Fragment,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  type RefObject,
} from "react";
import { createPortal } from "react-dom";
import { SCENE_ROOT } from "./Chrome";
import {
  Bell,
  EthernetPort,
  Folder,
  FolderSync,
  Gauge,
  LayoutGrid,
  ListTodo,
  Menu,
  MessageSquare,
  MessagesSquare,
  Monitor,
  Plus,
  Settings,
  type LucideIcon,
} from "lucide-react";

/* --------------------------------------------------------------- tooltip -- */

interface Tip {
  text: string;
  x: number;
  y: number;
  flip: boolean;
}

/**
 * One tooltip for every scene, built like the app's (src/ui/Tooltip.tsx): it
 * picks up any element in a scene carrying a `title`, moves the text into
 * `data-tip` so the browser's own tooltip never fires, and shows the app's
 * bubble under it (above it near the bottom of the window) after 340ms.
 */
export function SceneTooltip() {
  const [tip, setTip] = useState<Tip | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const current = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const resolve = (start: EventTarget | null): HTMLElement | null => {
      if (!(start instanceof Element) || !start.closest(".pz")) return null;
      const el = start.closest<HTMLElement>("[data-tip],[title]");
      return el && el.closest(".pz") ? el : null;
    };
    const hide = () => {
      clearTimeout(timer.current);
      current.current = null;
      setTip(null);
    };
    const show = (el: HTMLElement) => {
      const native = el.getAttribute("title");
      if (native) {
        el.setAttribute("data-tip", native);
        el.removeAttribute("title");
        if (!el.hasAttribute("aria-label") && !el.textContent?.trim()) el.setAttribute("aria-label", native);
      }
      const text = el.getAttribute("data-tip");
      if (!text) return;
      clearTimeout(timer.current);
      current.current = el;
      timer.current = setTimeout(() => {
        if (current.current !== el || !el.isConnected) return;
        const r = el.getBoundingClientRect();
        const flip = r.bottom > window.innerHeight - 52;
        setTip({
          text,
          x: Math.min(Math.max(r.left + r.width / 2, 56), window.innerWidth - 56),
          y: flip ? r.top - 8 : r.bottom + 8,
          flip,
        });
      }, 340);
    };
    const onOver = (e: MouseEvent) => {
      const el = resolve(e.target);
      if (el === current.current) return;
      if (el) show(el);
      else hide();
    };
    document.addEventListener("mouseover", onOver);
    document.addEventListener("pointerdown", hide, true);
    window.addEventListener("scroll", hide, true);
    return () => {
      clearTimeout(timer.current);
      document.removeEventListener("mouseover", onOver);
      document.removeEventListener("pointerdown", hide, true);
      window.removeEventListener("scroll", hide, true);
    };
  }, []);

  if (!tip) return null;
  return createPortal(
    <div className="pz pz-tip-host" {...SCENE_ROOT}>
      <div className={`pzza-tooltip ${tip.flip ? "flip" : ""}`} role="tooltip" style={{ left: tip.x, top: tip.y }}>
        {tip.text}
      </div>
    </div>,
    document.body,
  );
}

/* --------------------------------------------------------------- dismiss -- */

/**
 * Closes an open panel on a press outside `root` or on Escape, like the app's
 * menus, but only within the panel's own scene: every scene shows its panel
 * open, and a click elsewhere on the page must not close it.
 */
export function useDismiss(open: boolean, root: RefObject<HTMLElement>, close: () => void) {
  useEffect(() => {
    if (!open) return;
    const scene = () => root.current?.closest(".pz") ?? null;
    const onDown = (e: PointerEvent) => {
      if (!(e.target instanceof Node)) return;
      const inScene = scene()?.contains(e.target) ?? false;
      if (inScene && !root.current?.contains(e.target)) close();
    };
    const onKey = (e: KeyboardEvent) => {
      const focus = document.activeElement;
      if (e.key === "Escape" && focus && scene()?.contains(focus)) close();
    };
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open, root, close]);
}

/* -------------------------------------------------------------- top bar -- */

export type ToolId = "tasks" | "agents" | "chat" | "sync" | "remote" | "ports" | "usage" | "bell" | "settings" | "new";

/** How the app wraps a tool's button (src/App.tsx): a Dropdown's `.menu-wrap`, or the tool's own wrapper. */
type ToolWrap = "dropdown" | "agent-sessions" | "status" | "plain";

interface ToolDef {
  id: ToolId;
  icon: LucideIcon;
  title: string;
  wrap: ToolWrap;
  /** The Dropdown's tourId, set as data-tour on its wrapper (on the button for a plain IconButton). */
  tour?: string;
  /** A corner count, and the tooltip and name it gives the button (Dropdown's cornerBadge, badgeLabel). */
  badge?: { count: string; label: string };
}

// The top bar's tools in the app's order and groups (src/App.tsx), with
// every item shown, as by default, and a second device (Devbox) added, which
// brings Sync projects and Remote desktop: work tools | status | settings and
// the bordered New session square.
const GROUPS: ToolDef[][] = [
  [
    { id: "tasks", icon: ListTodo, title: "Tasks (⇧⌘T)", wrap: "dropdown", tour: "tasks", badge: { count: "1", label: "Tasks: 1 needs you" } },
    { id: "agents", icon: MessagesSquare, title: "Agent sessions", wrap: "agent-sessions" },
    { id: "chat", icon: MessageSquare, title: "Quick Chat", wrap: "dropdown", tour: "quick-chat" },
    { id: "sync", icon: FolderSync, title: "Sync projects", wrap: "status" },
    { id: "remote", icon: Monitor, title: "Remote desktop", wrap: "dropdown", tour: "remote" },
    { id: "ports", icon: EthernetPort, title: "Port manager", wrap: "dropdown", tour: "ports", badge: { count: "2", label: "Port manager: 2 forwarded ports" } },
  ],
  [
    { id: "usage", icon: Gauge, title: "Agent usage", wrap: "dropdown", tour: "usage" },
    { id: "bell", icon: Bell, title: "Notifications", wrap: "dropdown", tour: "notifications", badge: { count: "3", label: "Notifications: 3 unread" } },
  ],
  [
    { id: "settings", icon: Settings, title: "Settings", wrap: "plain", tour: "settings" },
    { id: "new", icon: Plus, title: "New session", wrap: "dropdown", tour: "new-session" },
  ],
];

/**
 * A tool's button: the app's IconButton (src/ui/IconButton.tsx), or the
 * Dropdown trigger with a corner badge (src/ui/Dropdown.tsx). An open one is lit.
 */
function ToolButton({ tool, open, onClick }: { tool: ToolDef; open: boolean; onClick: () => void }) {
  const { icon: Icon, badge, wrap, tour } = tool;
  const title = badge?.label ?? tool.title;
  const className = `icon-btn${open ? " icon-btn-on" : ""}`;
  if (badge) {
    return (
      <button type="button" className={className} title={title} aria-label={title} onClick={onClick}>
        <span className="toolbar-icon-anchor">
          <Icon size={16} strokeWidth={1.9} aria-hidden="true" />
          <span className="corner-badge" aria-hidden="true">
            {badge.count}
          </span>
        </span>
      </button>
    );
  }
  return (
    <button type="button" className={className} title={title} aria-label={title} data-tour={wrap === "plain" ? tour : undefined} onClick={onClick}>
      <span className="icon-inner">
        <Icon size={16} strokeWidth={1.9} />
      </span>
    </button>
  );
}

function wrapTool(tool: ToolDef, button: ReactNode) {
  switch (tool.wrap) {
    case "dropdown":
      return (
        <div key={tool.id} className="menu-wrap" data-tour={tool.tour}>
          {button}
        </div>
      );
    case "agent-sessions":
      return (
        <span key={tool.id} className="topbar-agent-sessions">
          {button}
        </span>
      );
    case "status":
      return (
        <div key={tool.id} className="toolbar-action-status">
          {button}
        </div>
      );
    case "plain":
      return <Fragment key={tool.id}>{button}</Fragment>;
  }
}

/**
 * The top bar's right side (src/App.tsx): the spacer and `.topbar-right` with
 * its tool cluster. A tool with a panel opens it as its dropdown (only one at
 * a time, like the app); the panels are rendered by the server and passed in,
 * absolutely placed against the top bar.
 *
 * A scene about one dropdown passes it as `initial` and keeps it pinned: the
 * section always shows what it is about. Another tool's dropdown can still be
 * opened, and closing that one brings the pinned dropdown back.
 *
 * The cluster's collapsed form (behind the Tools button) is for windows up to
 * 1080px wide; a scene's window is wider, so it stays inline (home.css).
 */
export function ToolsBar({ initial, panels }: { initial?: ToolId; panels: Partial<Record<ToolId, ReactNode>> }) {
  const pinned = initial ?? null;
  const [open, setOpen] = useState<ToolId | null>(pinned);
  const root = useRef<HTMLDivElement>(null);
  const close = useCallback(() => setOpen(pinned), [pinned]);
  useDismiss(open !== null && open !== pinned, root, close);
  const toggle = (id: ToolId) => {
    if (!panels[id] || id === pinned) {
      if (id === pinned) setOpen(pinned);
      return;
    }
    setOpen((value) => (value === id ? pinned : id));
  };
  return (
    <>
      <div className="topbar-spacer" />
      <div className="topbar-right" ref={root}>
        <div className="topbar-tools-wrap">
          <button type="button" className="icon-btn topbar-tools-toggle" title="Tools" aria-label="Tools">
            <span className="icon-inner">
              <Menu size={16} strokeWidth={1.9} />
            </span>
          </button>
          <div className="topbar-tools">
            {GROUPS.map((group, g) => [
              g > 0 ? <span key={`sep-${g}`} className="topbar-tools-sep" aria-hidden="true" /> : null,
              ...group.map((tool) => wrapTool(tool, <ToolButton tool={tool} open={open === tool.id} onClick={() => toggle(tool.id)} />)),
            ])}
          </div>
        </div>
        {open && panels[open] ? <div className="pz-dropdown">{panels[open]}</div> : null}
      </div>
    </>
  );
}

/* --------------------------------------------------------------- canvas -- */

interface TileSlotState {
  active: boolean;
}

const ACTIVE_SLOT: TileSlotState = { active: true };
const INACTIVE_SLOT: TileSlotState = { active: false };
const TileSlot = createContext<TileSlotState | null>(null);

/** Whether the tile is the active one of its ActiveCanvas; null outside one. */
export function useTileSlot(): TileSlotState | null {
  return useContext(TileSlot);
}

/**
 * The app's canvas (src/App.tsx, src/grid/Canvas.tsx): `.body` > `main.canvas`
 * > `.grid` holding the tiles. Its tiles activate on press, like the app: the
 * active tile is clear and the others get the inactive wash (the classes the
 * app sets, through useTileSlot). `style` is the grid's track layout. The
 * tiles are server markup, one element each.
 */
export function ActiveCanvas({
  tiles,
  initial = 0,
  style,
  active: controlled,
  onActivate,
  canvasRef,
}: {
  tiles: ReactNode[];
  initial?: number;
  style?: CSSProperties;
  /** Set by a scene that drives the focus itself (the hero's loop). */
  active?: number;
  onActivate?: (index: number) => void;
  canvasRef?: RefObject<HTMLElement>;
}) {
  const [own, setOwn] = useState(initial);
  const active = controlled ?? own;
  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!(event.target instanceof Element)) return;
    const tile = event.target.closest(".tile");
    if (!tile || tile.parentElement !== event.currentTarget) return;
    const index = Array.prototype.indexOf.call(event.currentTarget.children, tile);
    setOwn(index);
    onActivate?.(index);
  };
  return (
    <div className="body">
      <main ref={canvasRef} className="canvas">
        <div className="grid" style={style} onPointerDown={onPointerDown}>
          {tiles.map((tile, i) => (
            <TileSlot.Provider key={i} value={i === active ? ACTIVE_SLOT : INACTIVE_SLOT}>
              {tile}
            </TileSlot.Provider>
          ))}
        </div>
      </main>
    </div>
  );
}

/* ------------------------------------------------------- workspace tabs -- */

const TABS: { name: string; color?: string; waiting?: number; all?: boolean }[] = [
  { name: "All", waiting: 1, all: true },
  { name: "fieldnotes", color: "#7aa2f7" },
  { name: "personal", color: "#9ece6a", waiting: 1 },
];

/** altBadge in src/shortcuts.ts, on macOS. */
const altBadge = (n: number) => `⌥${n}`;

/** The tabs' waiting count (WorkspaceTabs' waitingBadge, countLabel in src/panels/Notifications.tsx). */
function WaitingBadge({ count, name }: { count?: number; name: string }) {
  if (!count) return null;
  return (
    <span className="corner-badge ws-tab-count" role="status" aria-label={`${count} session${count === 1 ? "" : "s"} waiting in ${name}`}>
      {count > 9 ? "9+" : String(count)}
    </span>
  );
}

interface StripPlace {
  left: number;
  maxWidth: number;
}

/**
 * The workspace tabs in the app's markup (src/grid/WorkspaceTabs.tsx). The
 * strip is placed like the app places it, from the real edges of the brand
 * and the tool cluster: centred on the bar whenever it fits. The tabs show
 * their hover and tooltips but stay put when clicked: the scene keeps the
 * workspace it was framed on. `kbd` shows the ⌥ hints, as windows over 900px do.
 */
export function WorkspaceTabs({ kbd = true, active = 1 }: { kbd?: boolean; active?: number }) {
  const ref = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [place, setPlace] = useState<StripPlace | null>(null);

  useLayoutEffect(() => {
    const strip = ref.current;
    const scroll = scrollRef.current;
    const bar = strip?.parentElement;
    const brand = bar?.querySelector<HTMLElement>(".brand");
    const right = bar?.querySelector<HTMLElement>(".topbar-right");
    if (!strip || !scroll || !bar || !brand || !right) return;
    const GAP = 10;
    // Layout offsets rather than client rects: the scene's Stage scales the
    // window, and the app's numbers are unscaled pixels.
    const measure = () => {
      const regionL = brand.offsetLeft + brand.offsetWidth + GAP;
      const regionR = right.offsetLeft - GAP;
      const region = Math.max(120, regionR - regionL);
      const addWrap = scroll.nextElementSibling instanceof HTMLElement ? scroll.nextElementSibling.offsetWidth : 0;
      const width = Math.min(scroll.scrollWidth + addWrap + 2, region);
      const centered = bar.offsetWidth / 2 - width / 2;
      const left = Math.round(Math.min(Math.max(centered, regionL), regionR - width));
      const maxWidth = Math.floor(width);
      setPlace((prev) => (prev && prev.left === left && prev.maxWidth === maxWidth ? prev : { left, maxWidth }));
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(bar);
    observer.observe(brand);
    observer.observe(right);
    observer.observe(scroll);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      className="ws-tabs"
      ref={ref}
      data-tour="workspaces"
      // Centred until measured; the measured place is the same whenever the tabs fit.
      style={place ? { left: place.left, maxWidth: place.maxWidth } : { left: "50%", transform: "translateX(-50%)" }}
    >
      <div className="ws-tabs-scroll" ref={scrollRef}>
        {TABS.map((tab, i) => {
          const body = (
            <div className={`ws-tab ${i === active ? "ws-tab-active" : ""}`} title={tab.all ? "All workspaces" : tab.name}>
              <span className="ws-tab-icon-anchor">
                {tab.all ? (
                  <LayoutGrid size={13} className="ws-tab-icon" />
                ) : (
                  <Folder size={13} className="ws-tab-icon" style={tab.color ? { color: tab.color } : undefined} />
                )}
                <WaitingBadge count={tab.waiting} name={tab.all ? "all workspaces" : tab.name} />
              </span>
              <span className="ws-tab-name">{tab.name}</span>
              {kbd ? <kbd className="kbd ws-kbd">{altBadge(i)}</kbd> : null}
            </div>
          );
          return tab.all ? (
            <Fragment key={tab.name}>{body}</Fragment>
          ) : (
            <div key={tab.name} className="ws-tab-wrap">
              {body}
            </div>
          );
        })}
      </div>
      <div className="ws-tab-wrap ws-tabs-add-wrap">
        <button type="button" className="ws-tab-add" title="New workspace (⇧⌘N)" aria-label="New workspace" aria-keyshortcuts="Meta+Shift+N">
          <Plus size={15} strokeWidth={2.2} />
        </button>
      </div>
    </div>
  );
}
